entries[4139] = { ["name"] = "Dschungelwandlersandalen", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n34 Rüstung\n+8 Ausdauer\n+5 Intelligenz\n+2 Willenskraft\nHaltbarkeit 35 / 35\nVerkaufspreis:" }
entries[4140] = { ["name"] = "Palmwedelmantel", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n34 Rüstung\n+7 Intelligenz\n+6 Willenskraft\nHaltbarkeit 45 / 45\nVerkaufspreis:" }
entries[4141] = { ["name"] = "Foliant des Essenherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 6\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 1).\nZaubert 20 Muffins herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezauberter Muffin\nHerbeigezauberter Gegenstand\nBenutzen: Stellt im Verlauf von 18 Sek. insgesamt 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4143] = { ["name"] = "Foliant des Essenherbeizauberns II", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 2).\nZaubert 20 Laibe Brot herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Brot\nHerbeigezauberter Gegenstand\nBenötigt Stufe 5\nBenutzen: Stellt im Verlauf von 21 Sek. insgesamt 243.6 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4145] = { ["name"] = "Foliant des Manaedelsteinherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 28\nBenutzen: Lehrt 'Manaedelstein herbeizaubern'.\nZaubert einen Manaachat herbei, der zum sofortigen Wiederherstellen von 390 bis 410 Mana verwendet werden kann.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nManaachat\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 28\nBenutzen: Stellt 390 bis 410 Mana wieder her. (2 Min Abklingzeit)" }
entries[4146] = { ["name"] = "Foliant der Verwandlung: Schaf", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Verwandlung: Schaf'.\nVerwandelt den Feind bis zu 10 Sek. lang in ein hilfloses Schaf, das weder Zauber wirken noch angreifen kann und sich um 60% langsamer bewegt.\nVerkaufspreis:" }
entries[4147] = { ["name"] = "Foliant des Essenherbeizauberns III", ["text"] = "Klassen: Magier\nBenötigt Stufe 22\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 3).\nZaubert 20 Laibe Roggenbrot herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Roggenbrot\nHerbeigezauberter Gegenstand\nBenötigt Stufe 15\nBenutzen: Stellt im Verlauf von 24 Sek. insgesamt 552 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4148] = { ["name"] = "Foliant des Gegenzaubers", ["text"] = "Klassen: Magier\nBenötigt Stufe 24\nBenutzen: Lehrt 'Gegenzauber'.\nKontert das Zauberwirken des Feindes und verhindert 8 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung.\nVerkaufspreis:" }
entries[4149] = { ["name"] = "Foliant des Frostschilds III", ["text"] = "Klassen: Magier\nBenötigt Stufe 34\nBenutzen: Lehrt 'Frostschild' (Rang 3).\nVerkaufspreis:" }
entries[4150] = { ["name"] = "Foliant des Wasserherbeizauberns IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 30\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 4).\nZaubert 20 Flaschen Quellwasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Quellwasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 Sek. insgesamt 1345 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[4151] = { ["name"] = "Foliant des Frostblitzes IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Frostblitz' (Rang 4).\nSchleudert einen Frostblitz auf den Feind, der 78 bis 87 Frostschaden verursacht und 7 Sek. lang das Bewegungstempo um 40% reduziert.\nVerkaufspreis:" }
entries[4152] = { ["name"] = "Foliant des Essenherbeizauberns IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 32\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 4).\nZaubert 20 Laibe Pumpernickel herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezauberter Pumpernickel\nHerbeigezauberter Gegenstand\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 Sek. insgesamt 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4153] = { ["name"] = "Foliant der arkanen Geschosse III", ["text"] = "Klassen: Magier\nBenötigt Stufe 24\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 3).\nSchleudert arkane Geschosse auf den Feind und verursacht 5 Sek. lang alle 1 Sek. 58 Arkanschaden.\nVerkaufspreis:" }
entries[4154] = { ["name"] = "Foliant der Verlangsamung II", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Langsamkeit' (Rang 2).\nVerlangsamt 15 Sek. lang die Bewegung des Feindes um 60% und sein Angriffstempo um 54%.\nVerkaufspreis:" }
entries[4155] = { ["name"] = "Foliant der Wasserelementare II", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Wasserelementar' (Rang 2).\nVerkaufspreis:" }
entries[4156] = { ["name"] = "Foliant des Manajuwelherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 37\nBenutzen: Lehrt 'Läutern'.\nLäutert ein befreundetes Ziel und hebt dabei 1 Krankheitseffekt und 1 Gifteffekt auf.\nVerkaufspreis:" }
entries[4157] = { ["name"] = "Foliant des Magiedämpfens", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Magie dämpfen' (Rang 1).\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 10 und Heilzauber um bis zu 20 verringert werden. Hält 10 Min. lang an.\nVerkaufspreis:" }
entries[4158] = { ["name"] = "Foliant von Khadgars Öffnung III", ["text"] = "Klassen: Magier\nBenötigt Stufe 42\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 4).\nBeschwört 15 Sek. lang ein Totem der Steinklaue mit 280 Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, 3 Sek. lang betäubt werden.\nVerkaufspreis:" }
entries[4159] = { ["name"] = "Foliant der arkanen Geschosse", ["text"] = "Klassen: Magier\nBenötigt Stufe 8\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 1).\nSchleudert arkane Geschosse auf den Feind und verursacht 3 Sek. lang alle 1 Sek. 26 Arkanschaden.\nVerkaufspreis:" }
entries[4161] = { ["name"] = "Foliant des Feuerballs IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 18\nBenutzen: Lehrt 'Feuerball' (Rang 4).\nSchleudert eine glühende Kugel hinaus, die 89 bis 122 Feuerschaden sowie 8 Sek. lang insgesamt 12 zusätzlichen Feuerschaden verursacht.\nVerkaufspreis:" }
entries[4162] = { ["name"] = "Foliant des Blinzelns II", ["text"] = "Klassen: Magier\nBenötigt Stufe 38\nBenutzen: Lehrt 'Blinzeln' (Rang 2).\nVerkaufspreis:" }
entries[4163] = { ["name"] = "Ausgedienter Buchband: Siegel des Furors", ["text"] = "Klassen: Paladin\nBenötigt Stufe 32\nBenutzen: Lehrt 'Siegel des Furors' (Rang 1).\nVerkaufspreis:" }
entries[4164] = { ["name"] = "Buchband: Heiliges Licht V", ["text"] = "Klassen: Paladin\nBenötigt Stufe 30\nBenutzen: Lehrt 'Heiliges Licht' (Rang 5).\nHeilt ein befreundetes Ziel um 506 bis 569.\nVerkaufspreis:" }
entries[4165] = { ["name"] = "Buchband: Heiliges Licht VI", ["text"] = "Klassen: Paladin\nBenötigt Stufe 38\nBenutzen: Lehrt 'Heiliges Licht' (Rang 6).\nHeilt ein befreundetes Ziel um 717 bis 799.\nVerkaufspreis:" }
entries[4166] = { ["name"] = "Buchband: Siegel des Schutzes", ["text"] = "Klassen: Paladin\nBenötigt Stufe 8\nBenutzen: Lehrt 'Siegel des Schutzes' (Rang 1).\nEin anvisiertes Gruppenmitglied ist 6 Sek. lang vor allen körperlichen Angriffen geschützt, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein. Einmal geschützt, kann das Ziel 1 Min. lang nicht erneut durch Gottesschild, Göttlicher Schutz oder Segen des Schutzes unverwundbar gemacht werden.\nVerkaufspreis:" }
entries[4167] = { ["name"] = "Buchband: Richturteil", ["text"] = "Klassen: Paladin\nBenötigt Stufe 40\nBenutzen: Lehrt 'Richturteil'.\nVerschleudert Blitze heiliger Macht in alle Richtungen und verursacht dabei 368 bis 435 Heiligschaden bei allen Untoten und Dämonen im Umkreis von 20 Metern.\nVerkaufspreis:" }
entries[4168] = { ["name"] = "Schrifttafel des Totems der Einschnürung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 16\nBenutzen: Lehrt 'Totem der Erdbindung' (Rang 1).\nBeschwört 45 Sek. lang ein Totem der Erdbindung mit 5 Gesundheit zu Füßen des Zaubernden, das das Bewegungstempo von Feinden im Umkreis von 10 Metern verlangsamt.\nVerkaufspreis:" }
entries[4169] = { ["name"] = "Schrifttafel des unerschütterlichen Willens II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 24\nBenutzen: Lehrt 'Unerschütterlicher Wille' (Rang 2).\nVerkaufspreis:" }
entries[4170] = { ["name"] = "Schrifttafel des astralen Rückrufs", ["text"] = "Klassen: Schamane\nBenötigt Stufe 30\nBenutzen: Lehrt 'Astraler Rückruf'.\nReißt den Zaubernden durch den wirbelnden Nether zurück nach Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\nVerkaufspreis:" }
entries[4171] = { ["name"] = "Schrifttafel des aufstachelnden Totems III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 28\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 3).\nBeschwört 15 Sek. lang ein Totem der Steinklaue mit 220 Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, 3 Sek. lang betäubt werden.\nVerkaufspreis:" }
entries[4172] = { ["name"] = "Schrifttafel des Donnerknalls II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 36\nBenutzen: Lehrt 'Donnerknall' (Rang 2).\nVerkaufspreis:" }
entries[4173] = { ["name"] = "Schrifttafel des Schocks IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 28\nBenutzen: Lehrt 'Schock' (Rang 4).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 191 bis 202 Schaden zu.\nVerkaufspreis:" }
entries[4174] = { ["name"] = "Schrifttafel des Schocks V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 36\nBenutzen: Lehrt 'Schock' (Rang 5).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 269 bis 286 Schaden zu.\nVerkaufspreis:" }
entries[4175] = { ["name"] = "Schrifttafel des Blitzschlagschildes IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Blitzschlagschild' (Rang 4).\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Fernkampf- oder Zauberangriff getroffen wird, erleidet der Angreifende 80 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein. (3.5s Abklingzeit)\nVerkaufspreis:" }
entries[4176] = { ["name"] = "Schrifttafel der unsterblichen Stärke II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 36\nBenutzen: Lehrt 'Unsterbliche Stärke' (Rang 2).\nVerkaufspreis:" }
entries[4177] = { ["name"] = "Schrifttafel des Naturwiderstands", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Naturwiderstand'.\nVerkaufspreis:" }
entries[4178] = { ["name"] = "Schrifttafel des Blitzschlags V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 34\nBenutzen: Lehrt 'Blitzschlag' (Rang 5).\nSchleudert einen Blitz auf das Ziel und fügt ihm 131 bis 149 Naturschaden zu.\nVerkaufspreis:" }
entries[4179] = { ["name"] = "Schrifttafel der Wiederherstellung V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Große Welle der Heilung' (Rang 1).\nHeilt ein befreundetes Ziel um 389 bis 454.\nVerkaufspreis:" }
entries[4180] = { ["name"] = "Schrifttafel der Astralgestalt II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 34\nBenutzen: Lehrt 'Astralgestalt' (Rang 2).\nVerkaufspreis:" }
entries[4181] = { ["name"] = "Schrifttafel des aufstachelnden Totems IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 38\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 4).\nBeschwört 15 Sek. lang ein Totem der Steinklaue mit 280 Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, 3 Sek. lang betäubt werden.\nVerkaufspreis:" }
entries[4182] = { ["name"] = "Schrifttafel des unerschütterlichen Willens III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 38\nBenutzen: Lehrt 'Unerschütterlicher Wille' (Rang 3).\nVerkaufspreis:" }
entries[4183] = { ["name"] = "Schrifttafel des Totems der Heilung V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 36\nBenutzen: Lehrt 'Totem der Heilung' (Rang 5).\nVerkaufspreis:" }
entries[4184] = { ["name"] = "Schrifttafel des Schmelzschlages V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 38\nBenutzen: Lehrt 'Schmelzschlag' (Rang 5).\nVerkaufspreis:" }
entries[4185] = { ["name"] = "Schrifttafel des astralen Gruppenrückrufs", ["text"] = "Klassen: Schamane\nBenötigt Stufe 40\nBenutzen: Lehrt 'Astraler Gruppenrückruf'.\nVerkaufspreis:" }
entries[4186] = { ["name"] = "Schrifttafel des Feuerwiderstands", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Feuerwiderstand'.\nVerkaufspreis:" }
entries[4187] = { ["name"] = "Schrifttafel des Schlangentotems V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 40\nVerkaufspreis:" }
entries[4188] = { ["name"] = "Schrifttafel des Totems der Unsichtbarkeit", ["text"] = "Klassen: Schamane\nBenötigt Stufe 40\nBenutzen: Lehrt 'Totem der Unsichtbarkeit'.\nVerkaufspreis:" }
entries[4189] = { ["name"] = "Schrifttafel des Kettenblitzschlages", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Kettenblitzschlag' (Rang 1).\nSchleudert einen Blitzschlag auf den Feind, der 200 bis 227 Naturschaden verursacht und zu in der Nähe befindlichen Feinden weiterspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele.\nVerkaufspreis:" }
entries[4190] = { ["name"] = "Gefiederte Rüstung", ["text"] = "Brust Leder\n84 Rüstung\nHaltbarkeit 80 / 80\nBenötigt Stufe 22\nVerkaufspreis:" }
entries[4191] = { ["name"] = "Ungenutzte gefiederte Gamaschen", ["text"] = "Beine Leder\n74 Rüstung\nHaltbarkeit 60 / 60\nBenötigt Stufe 22\nVerkaufspreis:" }
entries[4192] = { ["name"] = "Ungenutzte gefiederte Stulpen", ["text"] = "Hände Leder\n53 Rüstung\nHaltbarkeit 30 / 30\nBenötigt Stufe 22\nVerkaufspreis:" }
entries[4193] = { ["name"] = "Ausgedienter gefiederter Helm", ["text"] = "Kopf Leder\n68 Rüstung\nHaltbarkeit 50 / 50\nBenötigt Stufe 22\nVerkaufspreis:" }
entries[4194] = { ["name"] = "Gefiederte Armschienen", ["text"] = "Handgelenke Leder\n37 Rüstung\nHaltbarkeit 30 / 30\nBenötigt Stufe 22\nVerkaufspreis:" }
entries[4195] = { ["name"] = "Gefiederte Stiefel", ["text"] = "Füße Leder\n58 Rüstung\nHaltbarkeit 40 / 40\nBenötigt Stufe 22\nVerkaufspreis:" }
entries[4196] = { ["name"] = "Gefiederter Mantel", ["text"] = "Wird beim Anlegen gebunden\nSchulter Leder\n77 Rüstung\nHaltbarkeit 60 / 60\nBenötigt Stufe 25\nVerkaufspreis:" }
entries[4197] = { ["name"] = "Beryllpolster", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n39 Rüstung\n+5 Ausdauer\n+10 Intelligenz\n+6 Willenskraft\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
entries[4198] = { ["name"] = "Zauberfoliant des Seelentrichters", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 12\nBenutzen: Lehrt 'Lebenslinie' (Rang 1).\nGibt dem Begleiter des Zaubernden 10 Sek. lang in jeder Sekunde 12 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert.\nVerkaufspreis:" }
entries[4199] = { ["name"] = "Zauberfoliant des Seelentrichters II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Lebenslinie' (Rang 2).\nGibt dem Begleiter des Zaubernden 10 Sek. lang in jeder Sekunde 24 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert.\nVerkaufspreis:" }
entries[4200] = { ["name"] = "Zauberfoliant des Feuerbrandes III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 22\nBenutzen: Lehrt 'Feuerbrand' (Rang 3).\nVerbrennt den Feind und fügt 53 Feuerschaden sowie 15 Sek. lang insgesamt 90 zusätzlichen Feuerschaden zu.\nVerkaufspreis:" }
entries[4201] = { ["name"] = "Zauberfoliant des Auges von Kilrogg", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 28\nBenutzen: Lehrt 'Auge von Kilrogg'.\nBeschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge bewegt sich schnell, ist jedoch sehr zerbrechlich.\nVerkaufspreis:" }
entries[4202] = { ["name"] = "Zauberfoliant der Furcht II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 24\nBenutzen: Lehrt 'Furcht' (Rang 2).\nErfüllt den Feind mit Furcht, woraufhin er bis zu 15 Sek. lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden.\nVerkaufspreis:" }
entries[4203] = { ["name"] = "Zauberfoliant der Pestilenz II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 26\nBenutzen: Lehrt 'Verderbnis' (Rang 2).\nVerdirbt das Ziel und verursacht 15 Sek. lang insgesamt 90 Schattenschaden.\nVerkaufspreis:" }
entries[4204] = { ["name"] = "Zauberfoliant des Seelentrichters III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 28\nBenutzen: Lehrt 'Lebenslinie' (Rang 3).\nGibt dem Begleiter des Zaubernden 10 Sek. lang in jeder Sekunde 43 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert.\nVerkaufspreis:" }
entries[4205] = { ["name"] = "Zauberfoliant des Feuerbrandes IV", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 34\nBenutzen: Lehrt 'Feuerbrand' (Rang 4).\nVerbrennt den Feind und fügt 101 Feuerschaden sowie 15 Sek. lang insgesamt 165 zusätzlichen Feuerschaden zu.\nVerkaufspreis:" }
entries[4206] = { ["name"] = "Zauberfoliant des Fluchs von Sargeras II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 24\nBenutzen: Lehrt 'Fluch der Pein' (Rang 2).\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 180 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein.\nVerkaufspreis:" }
entries[4207] = { ["name"] = "Zauberfoliant des Fluchs von Archimonde", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 30\nBenutzen: Lehrt 'Archimondes Fluch'.\nVerflucht das Ziel mit drohender Verdammnis und fügt nach 1 Min. 3200 Schattenschaden zu. Wenn das Ziel durch diesen Schaden stirbt, besteht die Chance, dass eine Verdammniswache beschworen wird. Kann nicht auf Spieler gewirkt werden.\nVerkaufspreis:" }
entries[4208] = { ["name"] = "Zauberfoliant der Gedankenbombe", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 32\nBenutzen: Lehrt 'Gedankenbombe'.\nVerkaufspreis:" }
entries[4209] = { ["name"] = "Zauberfoliant des Schattenzauberschutzes", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 30\nBenutzen: Lehrt 'Schattenzauberschutz'.\nAbsorbiert 290 Schattenschaden. Hält 30 Sek. lang an.\nVerkaufspreis:" }
entries[4210] = { ["name"] = "Zauberfoliant der geringen Blutsteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 14\nBenutzen: Lehrt 'Geringen Gesundheitsstein herstellen'.\nLässt einen geringen Gesundheitsstein entstehen, der verwendet werden kann, um 250 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:" }
entries[4211] = { ["name"] = "Zauberfoliant der Pestilenz", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 14\nBenutzen: Lehrt 'Verderbnis' (Rang 1).\nVerdirbt das Ziel und verursacht 12 Sek. lang insgesamt 40 Schattenschaden.\nVerkaufspreis:" }
entries[4212] = { ["name"] = "Zauberfoliant des Fluchs von Mannoroth III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 32\nBenutzen: Lehrt 'Fluch der Schwäche' (Rang 3).\nDie Nahkampfangriffskraft des Ziels wird 2 Min. lang um 64 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein.\nVerkaufspreis:" }
entries[4213] = { ["name"] = "Zauberfoliant der Verdammnis", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Lehrt das Ritual der Verdammnis.\nBeginnt ein Ritual, das einen zufälligen Teilnehmer opfert, um eine Verdammniswache zu beschwören. Die Verdammniswache muss sofort unterworfen werden, sonst wird sie die Teilnehmer des Rituals angreifen. Um das Ritual zu vervollständigen, werden der Zaubernde und 4 zusätzliche Gruppenmitglieder benötigt. Um teilzunehmen, müssen alle Spieler auf das Portal rechtsklicken und dürfen sich nicht bewegen, bis das Ritual abgeschlossen ist.\nVerkaufspreis:" }
entries[4214] = { ["name"] = "Zauberfoliant des Lebenssaugers III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 30\nBenutzen: Lehrt 'Blutsauger' (Rang 3).\nÜberträgt alle 1 Sek. 29 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an.\nVerkaufspreis:" }
entries[4215] = { ["name"] = "Zauberfoliant des Feuerregens", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Feuerregen' (Rang 1).\nLässt einen feurigen Regen niedergehen, der 8 Sek. lang Feinde im Wirkungsbereich mit insgesamt ( 44 * 4) Feuerschaden verbrennt.\nVerkaufspreis:" }
entries[4216] = { ["name"] = "Zauberfoliant des heiligen Zauberschutzes", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Heiliger Zauberschutz'.\nVerkaufspreis:" }
entries[4217] = { ["name"] = "Zauberfoliant des Seelentrichters IV", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 36\nBenutzen: Lehrt 'Lebenslinie' (Rang 4).\nGibt dem Begleiter des Zaubernden 10 Sek. lang in jeder Sekunde 64 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert.\nVerkaufspreis:" }
entries[4218] = { ["name"] = "Zauberfoliant der Blutsteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 26\nBenutzen: Lehrt 'Gesundheitsstein herstellen'.\nLässt einen Gesundheitsstein entstehen, der verwendet werden kann, um sofort 500 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:" }
entries[4219] = { ["name"] = "Zauberfoliant des brennenden Geistes IV", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Brennender Geist' (Rang 4).\nVerkaufspreis:" }
entries[4220] = { ["name"] = "Zauberfoliant des Siedebluts III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 30\nBenutzen: Lehrt 'Siedeblut' (Rang 3).\nVerkaufspreis:" }
entries[4221] = { ["name"] = "Zauberfoliant der Entdeckung von Unsichtbarkeit", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Unsichtbarkeit entdecken'.\nVerkaufspreis:" }
entries[4223] = { ["name"] = "Buch des Magie Aufhebens", ["text"] = "Klassen: Druide\nBenötigt Stufe 36\nBenutzen: Lehrt 'Magie aufheben' (Rang 1).\nVerkaufspreis:" }
entries[4225] = { ["name"] = "Buch der Wucherwurzeln III", ["text"] = "Klassen: Druide\nBenötigt Stufe 28\nBenutzen: Lehrt 'Wucherwurzeln' (Rang 3).\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht 18 Sek. lang insgesamt 90 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen. Kann nur draußen verwendet werden.\nVerkaufspreis:" }
entries[4226] = { ["name"] = "Buch des Zorns VI", ["text"] = "Klassen: Druide\nBenötigt Stufe 38\nBenutzen: Lehrt 'Zorn' (Rang 6).\nVerursacht 148 bis 167 Naturschaden am Ziel.\nVerkaufspreis:" }
entries[4228] = { ["name"] = "Buch des Mondfeuers IV", ["text"] = "Klassen: Druide\nBenötigt Stufe 22\nBenutzen: Lehrt 'Mondfeuer' (Rang 4).\nVerbrennt den Feind und fügt ihm 47 bis 55 Arkanschaden sowie 12 Sek. lang insgesamt 80 zusätzlichen Arkanschaden zu.\nVerkaufspreis:" }
entries[4230] = { ["name"] = "Buch der heilenden Berührung VI", ["text"] = "Klassen: Druide\nBenötigt Stufe 32\nBenutzen: Lehrt 'Heilende Berührung' (Rang 6).\nHeilt ein befreundetes Ziel um 762 bis 914.\nVerkaufspreis:" }
