entries[4262] = { ["name"] = "Edelsteinbesetzter Ledergürtel", ["text"] = "Wird beim Anlegen gebunden\nTaille Leder\n65 Rüstung\n+8 Ausdauer\n+6 Willenskraft\nHaltbarkeit 35 / 35\nBenötigt Stufe 32\nBenutzen: Heilt Euch selbst um 225 bis 375. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[4263] = { ["name"] = "Standardausrüstungsschild", ["text"] = "Schildhand Schild\n161 Rüstung\n3 Blocken\nHaltbarkeit 45 / 45\nBenötigt Stufe 5\nVerkaufspreis:" }
entries[4264] = { ["name"] = "Barbarischer Gürtel", ["text"] = "Wird beim Anlegen gebunden\nTaille Leder\n62 Rüstung\n+11 Stärke\nHaltbarkeit 30 / 30\nBenötigt Stufe 35\nBenutzen: Wut um 30 erhöhen. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[4265] = { ["name"] = "Schweres Rüstungsset", ["text"] = "Benötigt Stufe 20\nBenutzen: Den Rüstungswert eines Gegenstands, der auf der Brust, an den Beinen, Händen oder Füßen getragen wird, dauerhaft um 24 erhöhen. Kann nur auf Gegenstände der Stufe 15 oder höher angewendet werden.\nVerkaufspreis:" }
entries[4266] = { ["name"] = "Kodex des inneren Feuers II", ["text"] = "Klassen: Priester\nBenötigt Stufe 20\nBenutzen: Lehrt 'Inneres Feuer' (Rang 2).\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 720 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 10 Min. lang an oder bis alle 20 Aufladungen verbraucht sind.\nVerkaufspreis:" }
entries[4267] = { ["name"] = "Kodex des Schattenwortes: Ungeschick", ["text"] = "Klassen: Priester\nBenötigt Stufe 20\nBenutzen: Lehrt 'Schattenwort: Ungeschick' (Rang 1).\nVerkaufspreis:" }
entries[4268] = { ["name"] = "Kodex der Heilung II", ["text"] = "Klassen: Priester\nBenötigt Stufe 22\nBenutzen: Lehrt 'Heilen' (Rang 2).\nEuer Ziel um 445 bis 507 heilen.\nVerkaufspreis:" }
entries[4269] = { ["name"] = "Kodex des Gebets der Heilung", ["text"] = "Klassen: Priester\nBenötigt Stufe 30\nBenutzen: Lehrt 'Gebet der Heilung' (Rang 1).\nEin wirkungsvolles Gebet heilt alle Gruppenmitglieder in einem Umkreis von 30 Metern um 312 bis 333.\nVerkaufspreis:" }
